const DEVICE_ID = "aqua_device_01";
const payload = msg.payload;

if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    node.warn("Telemetry không phải JSON object");
    return null;
}

const temperature = payload.temperature;
const ph = payload.ph;
const relayOn = payload.relayOn;

if (temperature !== null && (!Number.isFinite(temperature) || temperature < -55 || temperature > 125)) {
    node.warn("Nhiệt độ không hợp lệ");
    return null;
}

if (ph !== null && (!Number.isFinite(ph) || ph < 0 || ph > 4095)) {
    node.warn("Giá trị pH không hợp lệ");
    return null;
}

if (typeof relayOn !== "boolean") {
    node.warn("relayOn phải là boolean");
    return null;
}

const now = new Date().toISOString();
const telemetry = {
    deviceId: DEVICE_ID,
    temperature,
    ph,
    relayOn,
    receivedAt: now
};

const previousStatus = global.get("deviceStatus") || {};
const status = {
    deviceId: DEVICE_ID,
    online: true,
    value: "online",
    changedAt: previousStatus.online ? (previousStatus.changedAt || now) : now,
    lastSeenAt: now,
    source: "telemetry"
};

global.set("latestTelemetry", telemetry);
global.set("deviceStatus", status);
msg.payload = telemetry;
return msg;

const DEVICE_ID = "aqua_device_01";
const value = String(msg.payload).trim().toLowerCase();

if (value !== "online" && value !== "offline") {
    node.warn("Trạng thái thiết bị không hợp lệ");
    return null;
}

const now = new Date().toISOString();
const previousStatus = global.get("deviceStatus") || {};
const status = {
    deviceId: DEVICE_ID,
    online: value === "online",
    value,
    changedAt: now,
    lastSeenAt: value === "online" ? now : (previousStatus.lastSeenAt || null),
    source: "mqtt-status"
};

global.set("deviceStatus", status);
msg.payload = status;
return msg;

const DEVICE_ID = "aqua_device_01";
const relayOn = msg.payload && msg.payload.relayOn;

msg.topic = `aqua-iot/nhom18/${DEVICE_ID}/relay/set`;
msg.payload = JSON.stringify({ relayOn });
msg.qos = 1;
msg.retain = false;
return msg;

const SAVE_INTERVAL = 60000;
const now = Date.now();
const lastSavedAt = context.get("lastSavedAt") || 0;

if (now - lastSavedAt < SAVE_INTERVAL) {
    return null;
}

context.set("lastSavedAt", now);
return msg;

const firebaseService = global.get("firebaseService");

if (!firebaseService) {
    node.error("Không tìm thấy Firebase service", msg);
    return null;
}

try {
    const saved = await firebaseService.saveTelemetry(msg.payload);

    node.status({
        fill: "green",
        shape: "dot",
        text: `Đã lưu ${saved.id}`
    });

    msg.payload = saved;
    return msg;
} catch (error) {
    node.status({
        fill: "red",
        shape: "ring",
        text: "Lỗi Firestore"
    });

    node.error(`Không thể lưu Firestore: ${error.message}`, msg);
    return null;
}

const TEMP_MIN = 24;
const TEMP_MAX = 30;
const PH_MIN = 500;
const PH_MAX = 700;

// 5 phút
const COOLDOWN = 5 * 60 * 1000;

const telemetry = msg.payload;
const now = Date.now();
const alerts = [];

const lastAlertTimes = context.get("lastAlertTimes") || {};

function addAlert(key, metric, direction, value, threshold, unit, message) {
    const lastTime = lastAlertTimes[key] || 0;
    if (now - lastTime < COOLDOWN) return;
    lastAlertTimes[key] = now;
    alerts.push({ deviceId: telemetry.deviceId, metric, direction, value, threshold, unit, message, createdAt: new Date().toISOString() });
}

if (Number.isFinite(telemetry.temperature)) {
    if (telemetry.temperature < TEMP_MIN) addAlert("temperature-low", "temperature", "low", telemetry.temperature, TEMP_MIN, "°C", "Nhiệt độ đang quá thấp");
    else if (telemetry.temperature > TEMP_MAX) addAlert("temperature-high", "temperature", "high", telemetry.temperature, TEMP_MAX, "°C", "Nhiệt độ đang quá cao");
}

if (Number.isFinite(telemetry.ph)) {
    if (telemetry.ph < PH_MIN) addAlert("ph-low", "ph", "low", telemetry.ph, PH_MIN, "pH", "pH đang quá thấp");
    else if (telemetry.ph > PH_MAX) addAlert("ph-high", "ph", "high", telemetry.ph, PH_MAX, "pH", "pH đang quá cao");
}

context.set("lastAlertTimes", lastAlertTimes);
if (alerts.length === 0) return null;
for (const alert of alerts) node.send({ payload: alert });
return null;

const token = env.get("TELEGRAM_BOT_TOKEN");
const chatId = env.get("TELEGRAM_CHAT_ID");
const alert = msg.payload;

if (!token || !chatId) {
    node.error(
        "Chưa cấu hình Telegram Bot Token hoặc Chat ID"
    );

    return null;
}

const time = new Date(
    alert.createdAt
).toLocaleString(
    "vi-VN",
    {
        timeZone: "Asia/Ho_Chi_Minh"
    }
);

msg.headers = {
    "Content-Type": "application/json"
};
msg.url = `https://api.telegram.org/bot${token}/sendMessage`;

msg.payload = {
    chat_id: chatId,
    text:
        `CẢNH BÁO AQUA IOT\n` +
        `Thiết bị: ${alert.deviceId}\n` +
        `Nội dung: ${alert.message}\n` +
        `Giá trị: ${alert.value} ${alert.unit}\n` +
        `Ngưỡng: ${alert.threshold} ${alert.unit}\n` +
        `Thời gian: ${time}`
};
return msg;

const DEVICE_ID = "aqua_device_01";
const OFFLINE_AFTER_MS = 10000;
const latest = global.get("latestTelemetry") || null;
const storedStatus = global.get("deviceStatus") || {
    deviceId: DEVICE_ID,
    online: false,
    value: "unknown",
    changedAt: null,
    lastSeenAt: null,
    source: "none"
};

const nowMs = Date.now();
const latestMs = latest ? new Date(latest.receivedAt).getTime() : 0;
const statusChangedMs = storedStatus.changedAt ? new Date(storedStatus.changedAt).getTime() : 0;
const telemetryAgeMs = latestMs ? Math.max(0, nowMs - latestMs) : null;
const telemetryIsRecent = telemetryAgeMs !== null && telemetryAgeMs <= OFFLINE_AFTER_MS;
const statusIsRecent = statusChangedMs > 0 && nowMs - statusChangedMs <= OFFLINE_AFTER_MS;
const newerOfflineStatus = storedStatus.value === "offline" && statusChangedMs >= latestMs;
const effectiveOnline = newerOfflineStatus
    ? false
    : telemetryIsRecent || (storedStatus.online && statusIsRecent);

const status = {
    ...storedStatus,
    deviceId: DEVICE_ID,
    online: effectiveOnline,
    value: effectiveOnline ? "online" : "offline",
    lastSeenAt: latest ? latest.receivedAt : (storedStatus.lastSeenAt || null),
    ageMs: telemetryAgeMs,
    source: telemetryIsRecent && latestMs >= statusChangedMs
        ? "telemetry"
        : storedStatus.source
};

msg.headers = { "Content-Type": "application/json" };
msg.payload = {
    latest,
    status,
    serverTime: new Date().toISOString()
};
return msg;

const DEVICE_ID = "aqua_device_01";
const relayOn = msg.payload && msg.payload.relayOn;

if (typeof relayOn !== "boolean") {
    msg.statusCode = 400;
    msg.payload = {
        ok: false,
        message: "relayOn phải là boolean"
    };
    return [null, msg];
}

const mqttMessage = {
    topic: `aqua-iot/nhom18/${DEVICE_ID}/relay/set`,
    payload: JSON.stringify({ relayOn }),
    qos: 1,
    retain: false
};

msg.statusCode = 202;
msg.payload = {
    ok: true,
    message: "Đã gửi lệnh đến ESP32",
    requestedRelayOn: relayOn
};
return [mqttMessage, msg];

const DEVICE_ID = "aqua_device_01";

const hours = Number(msg.req.query.hours ?? 24);
const limit = Number(msg.req.query.limit ?? 1440);

msg.headers = {
    "Content-Type": "application/json"
};

if (
    !Number.isInteger(hours) ||
    hours < 1 ||
    hours > 168
) {
    msg.statusCode = 400;
    msg.payload = {
        ok: false,
        message: "hours phải là số nguyên từ 1 đến 168"
    };

    return msg;
}

if (
    !Number.isInteger(limit) ||
    limit < 1 ||
    limit > 10080
) {
    msg.statusCode = 400;
    msg.payload = {
        ok: false,
        message: "limit phải là số nguyên từ 1 đến 10080"
    };

    return msg;
}

const firebaseService = global.get("firebaseService");

if (!firebaseService) {
    msg.statusCode = 500;
    msg.payload = {
        ok: false,
        message: "Không tìm thấy Firebase service"
    };

    return msg;
}

try {
    const history =
        await firebaseService.readTelemetryHistory({
            hours,
            limit
        });

    msg.statusCode = 200;
    msg.payload = {
        deviceId: DEVICE_ID,
        hours,
        count: history.length,
        history,
        serverTime: new Date().toISOString()
    };
} catch (error) {
    node.error(
        `Không thể đọc lịch sử Firestore: ${error.message}`,
        msg
    );

    msg.statusCode = 500;
    msg.payload = {
        ok: false,
        message: "Không thể đọc lịch sử từ Firestore"
    };
}

return msg;

const DEVICE_ID = "aqua_device_01";
const payload = msg.payload;

msg.headers = {
    "Content-Type": "application/json"
};

if (
    !payload ||
    typeof payload.question !== "string" ||
    !payload.question.trim()
) {
    msg.statusCode = 400;

    msg.payload = {
        ok: false,
        message: "Câu hỏi không được để trống"
    };

    return msg;
}

const openaiService =
    global.get("openaiService");

if (!openaiService) {
    msg.statusCode = 500;

    msg.payload = {
        ok: false,
        message: "Không tìm thấy OpenAI service"
    };

    return msg;
}

const latest =
    global.get("latestTelemetry") || null;

const status =
    global.get("deviceStatus") || null;

const aquaContext = {
    deviceId: DEVICE_ID,
    latest: latest,
    status: status,
    thresholds: {
        temperatureMin: 24,
        temperatureMax: 30,
        phMin: 500,
        phMax: 700
    },
    serverTime: new Date().toISOString()
};

try {
    node.status({
        fill: "blue",
        shape: "dot",
        text: "Đang hỏi OpenAI"
    });

    const result =
        await openaiService.askAquaAssistant(
            payload.question,
            aquaContext
        );

    node.status({
        fill: "green",
        shape: "dot",
        text: "Đã trả lời"
    });

    msg.statusCode = 200;

    msg.payload = {
        ok: true,
        answer: result.answer,
        model: result.model,
        serverTime: new Date().toISOString()
    };
} catch (error) {
    node.status({
        fill: "red",
        shape: "ring",
        text: "Lỗi OpenAI"
    });

    node.error(
        `Không thể gọi OpenAI: ${error.message}`,
        msg
    );

    msg.statusCode = 500;

    msg.payload = {
        ok: false,
        message: "Không thể tạo câu trả lời"
    };
}

return msg;
